CREATE FUNCTION ops.file_scope(file_id uuid) RETURNS TABLE(user_id uuid,workspace_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT w.owner_user_id,w.id FROM files.private_attachment f JOIN core.workspace w ON w.id=f.workspace_id JOIN core.user_profile p ON p.user_id=w.owner_user_id WHERE f.id=file_id AND w.state='active' AND p.lifecycle='active' $$;
CREATE FUNCTION ops.file_candidates(after_id uuid DEFAULT '00000000-0000-0000-0000-000000000000') RETURNS TABLE(id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT f.id FROM files.private_attachment f WHERE f.id>after_id AND (f.status IN ('quarantined','deleting','rejected') OR f.status='pending_upload' AND (f.uploaded_at IS NOT NULL OR f.expires_at<clock_timestamp())) AND (f.scan_lease_until IS NULL OR f.scan_lease_until<clock_timestamp()) ORDER BY f.id LIMIT 100 $$;
REVOKE ALL ON FUNCTION ops.file_scope(uuid),ops.file_candidates(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION ops.file_scope(uuid),ops.file_candidates(uuid) TO worker_domain;
