CREATE FUNCTION files.guard_attachment() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r core.command_receipt; total bigint;
BEGIN
 IF TG_OP='DELETE' THEN IF current_user='lifecycle_operator' AND ops.purge_scope_allowed(OLD.workspace_id) AND OLD.status='deleted' THEN RETURN OLD; END IF; RAISE EXCEPTION 'file bytes must be cleaned before metadata purge' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.workspace_id,NEW.object_key,NEW.bucket_key,NEW.object_version,NEW.original_filename,NEW.declared_mime,NEW.declared_bytes,NEW.created_by_user_id,NEW.created_at,NEW.expires_at) IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.object_key,OLD.bucket_key,OLD.object_version,OLD.original_filename,OLD.declared_mime,OLD.declared_bytes,OLD.created_by_user_id,OLD.created_at,OLD.expires_at) THEN RAISE EXCEPTION 'file identity immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'file version invalid' USING ERRCODE='23514'; END IF;
 IF current_user='lifecycle_operator' AND ops.purge_scope_allowed(NEW.workspace_id) THEN IF TG_OP<>'UPDATE' OR NEW.status<>'deleted' OR NEW.deleted_at IS NULL THEN RAISE EXCEPTION 'file purge transition invalid'; END IF; RETURN NEW; END IF;
 IF current_user='app_domain' THEN
  SELECT * INTO r FROM core.command_receipt WHERE workspace_id=NEW.workspace_id AND id=NEW.command_receipt_id;
  IF r.state IS DISTINCT FROM 'claimed' OR r.command_type NOT IN ('files.reserve','files.upload','files.unlink','files.delete') THEN RAISE EXCEPTION 'file command required' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' THEN
   IF r.command_type<>'files.reserve' OR NEW.created_by_user_id<>NULLIF(current_setting('app.user_id',true),'')::uuid OR NEW.status<>'pending_upload' OR NEW.actual_bytes IS NOT NULL OR NEW.checksum_sha256 IS NOT NULL OR NEW.uploaded_at IS NOT NULL OR NEW.scan_claim_id IS NOT NULL OR NEW.scan_lease_until IS NOT NULL OR NEW.object_key<>'evidence/'||NEW.workspace_id||'/'||NEW.id THEN RAISE EXCEPTION 'pending file reservation invalid'; END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended(NEW.workspace_id||':files',0)); SELECT COALESCE(sum(declared_bytes),0) INTO total FROM files.private_attachment WHERE workspace_id=NEW.workspace_id AND status<>'deleted'; IF total+NEW.declared_bytes>1073741824 THEN RAISE EXCEPTION 'file quota exceeded' USING ERRCODE='23514'; END IF;
  ELSE
   IF NEW.command_receipt_id=OLD.command_receipt_id OR (r.command_type='files.upload' AND (OLD.status<>'pending_upload' OR OLD.uploaded_at IS NOT NULL OR NEW.uploaded_at IS NULL OR NEW.status<>OLD.status)) OR (r.command_type='files.delete' AND NEW.status<>'deleting') OR (r.command_type='files.unlink' AND ROW(NEW.status,NEW.uploaded_at) IS DISTINCT FROM ROW(OLD.status,OLD.uploaded_at)) THEN RAISE EXCEPTION 'file mutation invalid'; END IF;
  END IF;
 ELSIF current_user='worker_domain' THEN
  IF TG_OP<>'UPDATE' OR NEW.command_receipt_id<>OLD.command_receipt_id OR OLD.status='deleted' OR (OLD.status='available' AND NEW.status NOT IN ('available','deleting')) OR (OLD.status='deleting' AND NEW.status NOT IN ('deleting','deleted')) THEN RAISE EXCEPTION 'file worker transition invalid'; END IF;
  IF OLD.status='available' AND ROW(NEW.actual_bytes,NEW.verified_mime,NEW.checksum_sha256,NEW.scan_engine_version,NEW.scan_result_code,NEW.scanned_at,NEW.uploaded_at) IS DISTINCT FROM ROW(OLD.actual_bytes,OLD.verified_mime,OLD.checksum_sha256,OLD.scan_engine_version,OLD.scan_result_code,OLD.scanned_at,OLD.uploaded_at) THEN RAISE EXCEPTION 'verified file evidence immutable'; END IF;
  IF NEW.status='available' AND (OLD.status<>'quarantined' OR OLD.scan_claim_id IS NULL OR OLD.scan_claim_id<>NEW.scan_claim_id OR OLD.scan_lease_until<clock_timestamp()) THEN RAISE EXCEPTION 'leased quarantined scan required'; END IF;
 ELSE RAISE EXCEPTION 'file role unavailable' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION files.guard_attachment() FROM PUBLIC;
CREATE TRIGGER file_guard BEFORE INSERT OR UPDATE OR DELETE ON files.private_attachment FOR EACH ROW EXECUTE FUNCTION files.guard_attachment();
CREATE TRIGGER file_active BEFORE INSERT OR UPDATE ON files.private_attachment FOR EACH ROW WHEN (current_user<>'lifecycle_operator') EXECUTE FUNCTION core.guard_active_private_domain_write();
CREATE FUNCTION files.validate_attachment_command() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF current_user='app_domain' AND NOT EXISTS(SELECT 1 FROM core.command_receipt c JOIN audit.private_revision a ON a.workspace_id=c.workspace_id AND a.command_receipt_id=c.id WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.state='completed' AND c.result_json->>'attachmentId'=NEW.id::text AND a.subject_id=NEW.id AND a.recorded_by_user_id=NEW.created_by_user_id) THEN RAISE EXCEPTION 'file command/audit incomplete' USING ERRCODE='23514'; END IF; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION files.validate_attachment_command() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER file_completion AFTER INSERT OR UPDATE ON files.private_attachment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION files.validate_attachment_command();
CREATE FUNCTION files.guard_attachment_link() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE s uuid; r core.command_receipt; BEGIN
 IF TG_OP='DELETE' THEN s:=OLD.workspace_id; ELSE s:=NEW.workspace_id; END IF;
 IF current_user='lifecycle_operator' AND ops.purge_scope_allowed(s) THEN RETURN OLD; END IF;
 SELECT * INTO r FROM core.command_receipt WHERE workspace_id=s AND id=NULLIF(current_setting('files.receipt_id',true),'')::uuid;
 IF r.state IS DISTINCT FROM 'claimed' OR r.command_type NOT IN ('files.reserve','files.unlink') THEN RAISE EXCEPTION 'file link command required' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSIF TG_OP='INSERT' THEN RETURN NEW; ELSE RAISE EXCEPTION 'file links cannot be rewritten'; END IF;
END $$;REVOKE ALL ON FUNCTION files.guard_attachment_link() FROM PUBLIC;
